agency_contract = frappe.form_dict.get('agency_contract')
doc = frappe.get_doc('Agency Contract', agency_contract)

if not doc.start_date or not doc.end_date or not doc.payment_cycle:
    frappe.throw('Please fill Start Date, End Date, and Payment Cycle first.')

intervals = {'Quarterly': 3, 'Half Yearly': 6, 'Yearly': 12}
months_step = intervals.get(doc.payment_cycle)

if not months_step:
    frappe.throw('Unknown Payment Cycle: ' + str(doc.payment_cycle))

doc.set('payments', [])

current_date = doc.start_date
counter = 0
while current_date <= doc.end_date:
    counter = counter + 1
    doc.append('payments', {
        'payment_no': 'P' + str(counter),
        'cycle_date': current_date,
        'payment_due_date': current_date,
        'paid': 0
    })
    current_date = frappe.utils.add_months(current_date, months_step)

doc.save(ignore_permissions=True)
frappe.db.commit()

frappe.response['message'] = {'ok': True, 'count': counter}

start_dt = frappe.utils.getdate(doc.start_date) if doc.start_date else None
end_dt = frappe.utils.getdate(doc.end_date) if doc.end_date else None

if start_dt and end_dt:
    months = (end_dt.year - start_dt.year) * 12 + (end_dt.month - start_dt.month)
    doc.term_months = months if months > 0 else 0

cycle_config = {
    'Quarterly': {'months': 3},
    'Half Yearly': {'months': 6},
    'Yearly': {'months': 12},
}

if start_dt and doc.payment_cycle:
    due_config = cycle_config.get(doc.payment_cycle)
    if due_config:
        doc.due_date = frappe.utils.add_months(start_dt, due_config['months'])

old = doc.get_doc_before_save()
if not old:
    inputs_changed = True
    frontline_turned_on = bool(doc.frontline_incentive)
else:
    old_start_dt = frappe.utils.getdate(old.start_date) if old.start_date else None
    old_end_dt = frappe.utils.getdate(old.end_date) if old.end_date else None
    inputs_changed = (
        old_start_dt != start_dt or
        old_end_dt != end_dt or
        old.payment_cycle != doc.payment_cycle
    )
    frontline_turned_on = (
        bool(doc.frontline_incentive) and not bool(old.frontline_incentive)
    )

if inputs_changed and start_dt and end_dt and doc.payment_cycle and doc.term_months:
    config = cycle_config.get(doc.payment_cycle)
    if config:
        months_per_cycle = config['months']
        total_months = int(doc.term_months) if doc.term_months else 0
        if months_per_cycle > 0 and total_months >= months_per_cycle:
            num_payments = total_months // months_per_cycle
            doc.set('payments', [])
            for i in range(num_payments):
                current_period_start = frappe.utils.add_months(start_dt, i * months_per_cycle)
                current_cycle_due = frappe.utils.add_months(current_period_start, months_per_cycle)
                # إضافة شهرين وتثبيت اليوم على 15
                final_payment_due_date = frappe.utils.add_months(current_cycle_due, 2).replace(day=15)
                
                doc.append('payments', {
                    'payment_no': 'Payment #' + str(i + 1),
                    'cycle_date': current_cycle_due,
                    'payment_due_date': final_payment_due_date,
                    'paid': 0
                })

# جدول frontline_payment
if not doc.frontline_incentive:
    doc.set('frontline_payment', [])
else:
    build_frontline = (
        frontline_turned_on
        or inputs_changed
        or not (doc.get('frontline_payment') or [])
    )
    frontline_config = cycle_config.get('Quarterly')
    if build_frontline and frontline_config and start_dt and end_dt and doc.term_months:
        months_per_cycle = frontline_config['months']
        total_months = int(doc.term_months) if doc.term_months else 0
        if months_per_cycle > 0 and total_months >= months_per_cycle:
            num_payments = total_months // months_per_cycle

            keep = {}
            for r in (doc.get('frontline_payment') or []):
                if r.payment_no and r.payment_no != 'Total':
                    keep[r.payment_no] = {
                        'paid': r.paid,
                        'message': r.message,
                        'payment_amount': r.payment_amount,
                    }

            doc.set('frontline_payment', [])
            for i in range(num_payments):
                current_period_start = frappe.utils.add_months(start_dt, i * months_per_cycle)
                current_cycle_due = frappe.utils.add_months(current_period_start, months_per_cycle)
                # إضافة شهرين وتثبيت اليوم على 15
                final_payment_due_date = frappe.utils.add_months(current_cycle_due, 2).replace(day=15)
                
                label = 'Payment #' + str(i + 1)
                prior = keep.get(label) or {}
                doc.append('frontline_payment', {
                    'payment_no': label,
                    'cycle_date': current_cycle_due,
                    'payment_due_date': final_payment_due_date,
                    'paid': prior.get('paid') or 0,
                    'message': prior.get('message') or '',
                    'payment_amount': prior.get('payment_amount') or 0
                })

if doc.frontline_incentive and doc.frontline_payment:
    doc.total_frontline_amount = sum(
        frappe.utils.flt(row.payment_amount)
        for row in doc.frontline_payment
        if row.payment_no != "Total"
    )
else:
    doc.total_frontline_amount = 0
